3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => {
6	  const result: Cell[] = [];
7	  for (let dx = -1; dx <= 1; dx++) {
8	    for (let dy = -1; dy <= 1; dy++) {
9	      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
10	    }
11	  }
12	  return result;
13	};
