15	export const nextGeneration = (cells: Cell[]): Cell[] => {
16	  const living = new Set(cells.map(key));
17	  const liveNeighborCount = (cell: Cell): number =>
18	    neighbors(cell).filter((n) => living.has(key(n))).length;
19	
20	  const candidates = new Map<string, Cell>();
21	  for (const cell of cells) {
22	    candidates.set(key(cell), cell);
23	    for (const n of neighbors(cell)) candidates.set(key(n), n);
24	  }
25	
26	  const survivors: Cell[] = [];
27	  for (const cell of candidates.values()) {
28	    const count = liveNeighborCount(cell);
29	    const isAlive = living.has(key(cell));
30	    if (isAlive ? count === 2 || count === 3 : count === 3) {
31	      survivors.push(cell);
32	    }
33	  }
34	  return survivors;
35	};
